<?php
$role=role_name();$doctor=doctor_for_current_user();$from=get_string('from',date('Y-m-01'));$to=get_string('to',date('Y-m-d'));if(!validate_date($from)||!validate_date($to)||$from>$to){$from=date('Y-m-01');$to=date('Y-m-d');}$doctorClause='';$doctorParams=[];if($role==='Doctor'){$doctorClause=' AND a.doctor_id=?';$doctorParams[]=$doctor['doctor_id'];}
$statusStmt=db()->prepare("SELECT a.status,COUNT(*) total FROM appointments a WHERE a.appointment_date BETWEEN ? AND ? $doctorClause GROUP BY a.status ORDER BY total DESC");$statusStmt->execute(array_merge([$from,$to],$doctorParams));$statusRows=$statusStmt->fetchAll();$deptStmt=db()->prepare("SELECT dep.department_name,COUNT(*) total FROM appointments a JOIN doctors d ON d.doctor_id=a.doctor_id JOIN departments dep ON dep.department_id=d.department_id WHERE a.appointment_date BETWEEN ? AND ? $doctorClause GROUP BY dep.department_id ORDER BY total DESC");$deptStmt->execute(array_merge([$from,$to],$doctorParams));$deptRows=$deptStmt->fetchAll();$maxStatus=max(1,...array_map(fn($r)=>(int)$r['total'],$statusRows?:[['total'=>1]]));$maxDept=max(1,...array_map(fn($r)=>(int)$r['total'],$deptRows?:[['total'=>1]]));$totalAppointments=array_sum(array_column($statusRows,'total'));$completed=0;$noShow=0;foreach($statusRows as $r){if($r['status']==='Completed')$completed=(int)$r['total'];if($r['status']==='No-show')$noShow=(int)$r['total'];}$revenue=has_role('Doctor')?0:(float)query_value("SELECT COALESCE(SUM(amount),0) FROM payments WHERE DATE(payment_date) BETWEEN ? AND ? AND payment_status='Completed'",[$from,$to]);$outstanding=has_role('Doctor')?0:(float)query_value("SELECT COALESCE(SUM(due_amount),0) FROM invoices WHERE status='Active'");$labSql="SELECT COUNT(*) FROM lab_request_items lri JOIN lab_requests lr ON lr.lab_request_id=lri.lab_request_id WHERE DATE(lr.requested_at) BETWEEN ? AND ?";$labParams=[$from,$to];if($role==='Doctor'){$labSql.=' AND lr.doctor_id=?';$labParams[]=$doctor['doctor_id'];}$labCount=(int)query_value($labSql,$labParams);
if(get_string('export')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="mediflow-appointments-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Status','Total']);foreach($statusRows as $r)fputcsv($out,[$r['status'],$r['total']]);fclose($out);exit;}
?>
<div class="page-header"><div><h2>Reports & analytics</h2><p>Operational summaries for the selected period.</p></div><div class="actions"><a class="btn btn-light" href="<?=e(route_url('reports',['from'=>$from,'to'=>$to,'export'=>'csv']))?>">Export CSV</a><button class="btn btn-light" data-print>Print</button></div></div><div class="card mb-2 no-print"><form method="get" class="actions"><input type="hidden" name="page" value="reports"><div class="field mb-0"><label>From</label><input class="input" type="date" name="from" value="<?=e($from)?>"></div><div class="field mb-0"><label>To</label><input class="input" type="date" name="to" value="<?=e($to)?>"></div><button class="btn btn-primary" style="margin-top:22px">Apply range</button></form></div><div class="grid grid-5 mb-2"><div class="card stat-card" style="--stat-color:#2563eb"><div><div class="stat-label">Appointments</div><div class="stat-value"><?=$totalAppointments?></div><div class="stat-note"><?=format_date($from)?> – <?=format_date($to)?></div></div><div class="stat-icon">◷</div></div><div class="card stat-card" style="--stat-color:#15803d"><div><div class="stat-label">Completed</div><div class="stat-value"><?=$completed?></div><div class="stat-note"><?=$totalAppointments?round($completed/$totalAppointments*100,1):0?>% completion</div></div><div class="stat-icon">✓</div></div><div class="card stat-card" style="--stat-color:#dc2626"><div><div class="stat-label">No-show</div><div class="stat-value"><?=$noShow?></div><div class="stat-note"><?=$totalAppointments?round($noShow/$totalAppointments*100,1):0?>% no-show rate</div></div><div class="stat-icon">!</div></div><div class="card stat-card" style="--stat-color:#0f766e"><div><div class="stat-label">Lab tests</div><div class="stat-value"><?=$labCount?></div><div class="stat-note">Requested items</div></div><div class="stat-icon">⚗</div></div><?php if(!has_role('Doctor')):?><div class="card stat-card" style="--stat-color:#7c3aed"><div><div class="stat-label">Revenue</div><div class="stat-value" style="font-size:22px"><?=money($revenue)?></div><div class="stat-note">Outstanding <?=money($outstanding)?></div></div><div class="stat-icon">৳</div></div><?php endif;?></div><div class="grid grid-2"><div class="card"><div class="card-header"><div><h3>Appointment status</h3><p>Distribution across the selected period.</p></div></div><div class="bar-chart"><?php foreach($statusRows as $r):?><div class="bar-row"><span><?=e($r['status'])?></span><div class="bar-track"><div class="bar-fill" style="width:<?=round($r['total']/$maxStatus*100)?>%"></div></div><strong><?=$r['total']?></strong></div><?php endforeach;?></div></div><div class="card"><div class="card-header"><div><h3>Department activity</h3><p>Appointments by clinical department.</p></div></div><div class="bar-chart"><?php foreach($deptRows as $r):?><div class="bar-row"><span><?=e($r['department_name'])?></span><div class="bar-track"><div class="bar-fill" style="width:<?=round($r['total']/$maxDept*100)?>%"></div></div><strong><?=$r['total']?></strong></div><?php endforeach;?></div></div></div>
